import axios from "axios";
import authHeader from "../utils/authHeader";

const API_URL = "http://localhost:5000/api/tasks";

// Get tasks
export const getTasks = async (params = {}) => {
  const res = await axios.get(API_URL, { headers: authHeader(), params });
  return res.data;
};

// Create task
export const createTask = async (taskData) => {
  const res = await axios.post(API_URL, taskData, { headers: authHeader() });
  return res.data;
};

// Update task
export const updateTask = async (id, taskData) => {
  const res = await axios.put(`${API_URL}/${id}`, taskData, { headers: authHeader() });
  return res.data;
};

// Delete task
export const deleteTask = async (id) => {
  const res = await axios.delete(`${API_URL}/${id}`, { headers: authHeader() });
  return res.data;
};
